import { sql } from "drizzle-orm";
import { customType, pgEnum, timestamp } from "drizzle-orm/pg-core";

/* Custom types. Defined locally rather than imported so the pinned drizzle-orm
   version cannot surprise us; three lines each, zero version risk. */
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});
export const tsvector = customType<{ data: string; driverData: string }>({
  dataType: () => "tsvector",
});
export const inet = customType<{ data: string; driverData: string }>({
  dataType: () => "inet",
});

/* Fresh builders per table — never share a column builder instance. */
export const timestamps = () => ({
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

/* The one constant that makes `<slug>__<tool>` unambiguous. Not configurable. */
export const NAME_SEPARATOR = "__";
export const SLUG_RE = "^[a-z0-9]([a-z0-9-]{0,62}[a-z0-9])?$"; // no '_' => no '__'
export const slugCheck = (col: unknown) => sql`${col} ~ ${sql.raw(`'${SLUG_RE}'`)}`;

export const serverType = pgEnum("server_type", [
  "stdio", "streamable-http", "sse", "openapi",
]);
export const visibility = pgEnum("visibility", ["private", "team", "public"]);
export const credentialMode = pgEnum("credential_mode", [
  "shared",      // one set of creds, stored in `secrets`, used for everyone
  "per_user",    // each caller must have a credential_binding or the call is denied
  "passthrough", // caller's own headers forwarded; nothing stored
]);
export const itemKind = pgEnum("item_kind", ["tool", "prompt", "resource"]);
export const secretScope = pgEnum("secret_scope", [
  "server_env", "server_header", "server_oauth_client",
  "credential", "upstream_access", "upstream_refresh",
]);
export const bindingTarget = pgEnum("binding_target", ["env", "header"]);
export const principalKind = pgEnum("principal_kind", [
  "user", "api_key", "oauth_token", "anonymous",
]);
export const outcome = pgEnum("outcome", [
  "ok", "error", "denied", "timeout", "not_found",
]);

/* `@better-auth/cli generate` writes packages/core/src/db/auth-schema.ts.
   We re-export it so ONE drizzle chain covers better-auth + our tables. */
export * from "../auth-schema.js";
import { user } from "../auth-schema.js";
export { user };

/* better-auth config (auth agent owns the values; we own the fact that the
   column lands on the generated `user` table, not a side table of ours):

   betterAuth({
     user: { additionalFields: {
       role: { type: "string", defaultValue: "member", input: false },
     }},
     plugins: [apiKey({...}), mcp({...})],
   })

   Facts the rest of this schema depends on:
   - user.id is TEXT, not uuid. Every FK to a person is text.
   - apiKey.id is TEXT. audit_event does NOT FK to it (see audit_event).
   - better-auth owns: user, session, account, verification, apikey,
     oauthClient, oauthAccessToken, oauthRefreshToken, oauthConsent,
     oauthClientAssertion. We never write DDL for those. */

import { boolean, check, index, jsonb, pgTable, text, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { user } from "./auth.js";
import { credentialMode, serverType, slugCheck, timestamps, visibility } from "./_shared.js";
import type { ServerConfig } from "./config-schema.js";

export const servers = pgTable("servers", {
  id: uuid().primaryKey().defaultRandom(),
  slug: text().notNull(),                 // route + namespace prefix
  name: text().notNull(),                 // free-form display name
  description: text(),
  type: serverType().notNull(),           // mirrors config.type; here so the UI
                                          // can filter without unpacking jsonb
  config: jsonb().$type<ServerConfig>().notNull(),
  enabled: boolean().notNull().default(true),
  ownerId: text().notNull().references(() => user.id, { onDelete: "restrict" }),
  visibility: visibility().notNull().default("private"),
  allowPrivateNetwork: boolean().notNull().default(false),
  credentialMode: credentialMode().notNull().default("shared"),
  ...timestamps(),
}, (t) => [
  uniqueIndex("servers_slug_uq").on(t.slug),
  check("servers_slug_fmt", slugCheck(t.slug)),
  check("servers_type_matches_config",
    sql`${t.type}::text = ${t.config}->>'type'`),
  // serves the servers list filtered to "mine", and makes the ownerId
  // ON DELETE RESTRICT check an index scan instead of a seq scan
  index("servers_owner_idx").on(t.ownerId),
]);

import { z } from "zod";

/** A secret value never appears inline. It is written to `secrets` and the
 *  config holds only this ref. One resolver in core walks the config and
 *  swaps refs for plaintext at connect time; nothing else may read `secrets`. */
export const SecretRef = z.object({ $secret: z.uuid() }).strict();
export const Secretable = z.union([z.string(), SecretRef]);

const Oauth = z.object({
  issuer: z.url().optional(),
  resource: z.url().optional(),            // RFC 8707 audience, MUST be sent
  clientIdMetadataUrl: z.url().optional(), // CIMD — preferred
  clientId: z.string().optional(),         // RFC 7591 DCR — deprecated fallback
  clientSecret: SecretRef.optional(),
  scopes: z.array(z.string()).default([]),
}).strict();

const Common = {
  oauth: Oauth.optional(),
  requestTimeoutMs: z.int().min(1_000).max(600_000).default(60_000),
  keepAlive: z.object({
    enabled: z.boolean(),
    intervalMs: z.int().min(5_000).default(30_000),
  }).optional(),
};

const EnvKey = z.string().regex(/^[A-Za-z_][A-Za-z0-9_]*$/);
const HeaderKey = z.string().regex(/^[A-Za-z0-9!#$%&'*+.^_`|~-]+$/);

export const StdioConfig = z.object({
  type: z.literal("stdio"),
  command: z.string().min(1),
  args: z.array(z.string()).default([]),
  env: z.record(EnvKey, Secretable).default({}),
  cwd: z.string().optional(),
  startOnDemand: z.boolean().default(false),      // prime once, then sleep
  idleShutdownMs: z.int().min(10_000).default(600_000),
  ...Common,
}).strict();

const HttpBase = {
  url: z.url(),
  headers: z.record(HeaderKey, Secretable).default({}),
  ...Common,
};
export const StreamableHttpConfig = z.object({ type: z.literal("streamable-http"), ...HttpBase }).strict();
export const SseConfig = z.object({ type: z.literal("sse"), ...HttpBase }).strict();

export const OpenApiConfig = z.object({
  type: z.literal("openapi"),
  spec: z.union([
    z.object({ kind: z.literal("url"), url: z.url() }),
    z.object({ kind: z.literal("inline"), document: z.record(z.string(), z.unknown()) }),
  ]),
  baseUrl: z.url().optional(),                    // overrides spec servers[0]
  headers: z.record(HeaderKey, Secretable).default({}),
  security: z.record(z.string(), Secretable).default({}), // schemeName -> value
  ...Common,
}).strict();

export const ServerConfig = z.discriminatedUnion("type", [
  StdioConfig, StreamableHttpConfig, SseConfig, OpenApiConfig,
]);
export type ServerConfig = z.infer<typeof ServerConfig>;

import { boolean, pgTable, primaryKey, text, uuid } from "drizzle-orm/pg-core";
import { itemKind, timestamps } from "./_shared.js";
import { servers } from "./servers.js";

/** Per-tool / per-prompt / per-resource overrides. Rows exist only for items
 *  that were actually overridden — absence means "enabled, upstream description". */
export const serverItemOverride = pgTable("server_item_override", {
  serverId: uuid().notNull().references(() => servers.id, { onDelete: "cascade" }),
  kind: itemKind().notNull(),
  itemName: text().notNull(),   // BARE upstream name. Never namespaced, never aliased.
  enabled: boolean().notNull().default(true),
  description: text(),          // null => use the upstream description
  ...timestamps(),
}, (t) => [
  primaryKey({ columns: [t.serverId, t.kind, t.itemName] }),
]);

import { check, index, jsonb, pgTable, primaryKey, text, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { user } from "./auth.js";
import { servers } from "./servers.js";
import { slugCheck, timestamps, visibility } from "./_shared.js";

export const groups = pgTable("groups", {
  id: uuid().primaryKey().defaultRandom(),
  slug: text().notNull(),
  name: text().notNull(),
  description: text(),
  ownerId: text().notNull().references(() => user.id, { onDelete: "restrict" }),
  visibility: visibility().notNull().default("private"),
  ...timestamps(),
}, (t) => [
  uniqueIndex("groups_slug_uq").on(t.slug),
  check("groups_slug_fmt", slugCheck(t.slug)),
  index("groups_owner_idx").on(t.ownerId),
]);

/** 'all' | string[] — the per-server item selection, exactly mcphub's shape
 *  (entities/Group.ts:23-33). Read and written as one object with its row,
 *  never filtered on => jsonb by the D1 rule. */
export type ItemSelection = "all" | string[];

export const groupServer = pgTable("group_server", {
  groupId: uuid().notNull().references(() => groups.id, { onDelete: "cascade" }),
  serverId: uuid().notNull().references(() => servers.id, { onDelete: "cascade" }),
  alias: text(),                 // renames the server on THIS route only
  tools: jsonb().$type<ItemSelection>().notNull().default(sql`'"all"'::jsonb`),
  prompts: jsonb().$type<ItemSelection>().notNull().default(sql`'"all"'::jsonb`),
  resources: jsonb().$type<ItemSelection>().notNull().default(sql`'"all"'::jsonb`),
  ...timestamps(),
}, (t) => [
  primaryKey({ columns: [t.groupId, t.serverId] }),
  // serves "which groups expose this server?" — needed to invalidate the
  // projected tool cache when a server's tools change
  index("group_server_server_idx").on(t.serverId),
  // two members of one group may not present the same alias
  uniqueIndex("group_server_alias_uq").on(t.groupId, t.alias)
    .where(sql`alias is not null`),
  check("group_server_alias_fmt", sql`alias is null or ${slugCheck(t.alias)}`),
]);

import { check, index, pgTable, smallint, text, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { user } from "./auth.js";
import { servers } from "./servers.js";
import { bytea, secretScope, timestamps } from "./_shared.js";

/** Envelope-encrypted values. The auth agent owns the crypto helper; this is
 *  the only table it writes to. AAD = the columns themselves, so a ciphertext
 *  copied to another server/user/label simply fails to decrypt. */
export const secrets = pgTable("secrets", {
  id: uuid().primaryKey().defaultRandom(),     // this uuid is the {$secret} ref
  scope: secretScope().notNull(),
  serverId: uuid().references(() => servers.id, { onDelete: "cascade" }),
  userId: text().references(() => user.id, { onDelete: "cascade" }),
  label: text().notNull(),   // env var name / header name / 'access_token'
  alg: text().notNull().default("aes-256-gcm"),
  keyVersion: smallint().notNull().default(1),
  iv: bytea().notNull(),
  ciphertext: bytea().notNull(),
  tag: bytea().notNull(),
  ...timestamps(),
}, (t) => [
  check("secrets_iv_len", sql`octet_length(${t.iv}) = 12`),
  check("secrets_tag_len", sql`octet_length(${t.tag}) = 16`),
  check("secrets_ct_len", sql`octet_length(${t.ciphertext}) between 1 and 65536`),
  // both indexes exist to make the ON DELETE CASCADE probe an index scan
  index("secrets_server_idx").on(t.serverId),
  index("secrets_user_idx").on(t.userId),
]);

/** AAD, byte-for-byte. Any change to these columns invalidates the ciphertext.
 *  aad = Buffer.from([scope, serverId ?? "", userId ?? "", label,
 *                     String(keyVersion)].join("\x1f"), "utf8") */

import { index, integer, pgTable, text, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { user } from "./auth.js";
import { servers } from "./servers.js";
import { secrets } from "./secrets.js";
import { bindingTarget, timestamps } from "./_shared.js";

/** One filled credential slot for one person on one server. Write-only from
 *  the API: the value is never read back over HTTP, only by core's resolver. */
export const credentialBindings = pgTable("credential_bindings", {
  id: uuid().primaryKey().defaultRandom(),
  serverId: uuid().notNull().references(() => servers.id, { onDelete: "cascade" }),
  userId: text().notNull().references(() => user.id, { onDelete: "cascade" }),
  target: bindingTarget().notNull(),   // env | header — where it gets injected
  slot: text().notNull(),              // the env var / header name being filled
  secretId: uuid().notNull().references(() => secrets.id, { onDelete: "restrict" }),
  revision: integer().notNull().default(1), // bumped on every write
  ...timestamps(),
}, (t) => [
  uniqueIndex("credential_bindings_slot_uq").on(t.serverId, t.userId, t.target, t.slot),
  index("credential_bindings_secret_idx").on(t.secretId), // RESTRICT probe
]);

/** `revision` reproduces mcphub principalRuntimeService.ts:41-137: core caches
 *  an isolated upstream runtime per (serverId, userId) and keys the cache entry
 *  on max(revision) for that pair. Editing a credential invalidates the child
 *  process without a broadcast. Rotate: UPDATE ... SET revision = revision + 1. */

import { index, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { user } from "./auth.js";
import { servers } from "./servers.js";
import { secrets } from "./secrets.js";
import { timestamps } from "./_shared.js";

/** A completed grant against an upstream server's AS. Token MATERIAL lives in
 *  `secrets`; this row is the filterable metadata that a secrets row has no
 *  room for (issuer, resource audience, scopes, expiry). */
export const upstreamOauthTokens = pgTable("upstream_oauth_tokens", {
  id: uuid().primaryKey().defaultRandom(),
  serverId: uuid().notNull().references(() => servers.id, { onDelete: "cascade" }),
  userId: text().references(() => user.id, { onDelete: "cascade" }), // null = shared grant
  issuer: text().notNull(),
  resource: text().notNull(),          // RFC 8707 — the audience we asked for
  scopes: text().array().notNull().default(sql`'{}'::text[]`),
  tokenType: text().notNull().default("Bearer"),
  accessSecretId: uuid().notNull().references(() => secrets.id, { onDelete: "restrict" }),
  refreshSecretId: uuid().references(() => secrets.id, { onDelete: "restrict" }),
  expiresAt: timestamp({ withTimezone: true }),
  ...timestamps(),
}, (t) => [
  uniqueIndex("upstream_oauth_user_uq").on(t.serverId, t.userId)
    .where(sql`user_id is not null`),
  uniqueIndex("upstream_oauth_shared_uq").on(t.serverId)
    .where(sql`user_id is null`),
  // serves the proactive refresh sweep: WHERE expires_at < now() + '5 min'
  index("upstream_oauth_expiry_idx").on(t.expiresAt)
    .where(sql`expires_at is not null`),
]);

import { bigint, index, inet as _, integer, jsonb, pgTable, smallint, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { bytea, inet, outcome, principalKind, timestamps } from "./_shared.js";

/** Append-only. NO foreign keys, by design: the log must outlive every row it
 *  references, and ON DELETE SET NULL would erase attribution at exactly the
 *  moment a key is revoked. Identity columns are plain text + a denormalized
 *  display name captured at write time. */
export const auditEvent = pgTable("audit_event", {
  id: bigint({ mode: "number" }).generatedAlwaysAsIdentity().primaryKey(),
  startedAt: timestamp({ withTimezone: true, precision: 3 }).notNull().defaultNow(),

  // correlation
  requestId: text().notNull(),        // inbound X-Request-Id or ours; [A-Za-z0-9._-]{1,64}
  traceId: text(),                    // 32-hex from W3C traceparent, for OTel joins
  protocolVersion: text(),            // '2025-11-25' | '2026-07-28' | null
  clientName: text(),                 // from _meta clientInfo (modern) or initialize (legacy)
  clientVersion: text(),

  // principal
  principalKind: principalKind().notNull(),
  userId: text(),
  userName: text(),
  apiKeyId: text(),
  apiKeyName: text(),
  sourceIp: inet(),
  userAgent: text(),

  // target
  method: text().notNull(),           // 'tools/call' | 'resources/read' | 'tools/list' | ...
  serverId: uuid(),
  serverSlug: text(),
  groupId: uuid(),
  groupSlug: text(),
  toolName: text(),                   // bare upstream name
  exposedName: text(),                // what the client actually sent, aliases included

  // outcome
  outcome: outcome().notNull(),
  errorCode: integer(),               // JSON-RPC code, e.g. -32020 HeaderMismatch
  errorReason: text(),                // OUR reason: 'item_disabled' | 'item_unknown' | ...
  errorMessage: text(),               // truncated to 512 chars at write time

  // cost
  durationMs: integer().notNull(),    // gateway-in to gateway-out
  upstreamMs: integer(),              // time inside the upstream call
  inputBytes: integer(),
  outputBytes: integer(),
  resultTokens: integer(),            // cl100k of the result — call-time context cost

  // payload (nullable BY DESIGN)
  inputKeys: text().array(),          // top-level arg names, recorded even when payload isn't
  inputHash: bytea(),                 // sha256, 32 bytes
  outputHash: bytea(),
  inputPayload: jsonb(),
  outputPayload: jsonb(),
  payloadOmittedReason: text(),       // 'policy' | 'credentialed' | 'too_large' | null

  createdAt: timestamps().createdAt,
}, (t) => [
  // the default live feed: ORDER BY started_at DESC LIMIT 50
  index("audit_started_idx").on(t.startedAt.desc()),
  // per-server drill-down + the 24h latency/error sparkline on a server card
  index("audit_server_idx").on(t.serverId, t.startedAt.desc()),
  // "what did this person / this key do" — the revocation post-mortem
  index("audit_user_idx").on(t.userId, t.startedAt.desc()),
  index("audit_key_idx").on(t.apiKeyId, t.startedAt.desc()),
  // jump from a pino log line or an OTel span straight to the event
  index("audit_request_idx").on(t.requestId),
  // the error feed and the error-rate tile; partial so it stays ~2% of the table
  index("audit_error_idx").on(t.startedAt.desc())
    .where(sql`outcome <> 'ok'`),
]);

import { index, integer, jsonb, pgTable, text, timestamp, uniqueIndex, uuid, vector } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { servers } from "./servers.js";
import { bytea, itemKind, timestamps, tsvector } from "./_shared.js";

export const EMBEDDING_DIM = 1536; // text-embedding-3-small; see the dim guard below

/** The single cached catalog of everything a server exposes. Serves three
 *  features off one row: the tool list (input_schema), context cost
 *  (token_cost), and smart routing (tsv + embedding). */
export const toolEmbedding = pgTable("tool_embedding", {
  id: uuid().primaryKey().defaultRandom(),
  serverId: uuid().notNull().references(() => servers.id, { onDelete: "cascade" }),
  kind: itemKind().notNull(),
  itemName: text().notNull(),        // BARE name; <slug>__<name> is composed at read
  title: text(),
  description: text(),
  inputSchema: jsonb().$type<Record<string, unknown>>(),
  schemaKeys: text().array().notNull().default(sql`'{}'::text[]`),

  // cl100k count of JSON.stringify({name, description, inputSchema}) —
  // computed once at sync, so context cost is SUM(), not a live recompute
  tokenCost: integer().notNull(),

  // the EXACT string handed to the embedder AND to to_tsvector, so lexical and
  // vector search can never drift. Built as:
  //   `${server.slug} ${server.name}: ${server.description}\n` +
  //   `${itemName}\n${description}\n${schemaKeys.join(" ")}`
  searchText: text().notNull(),
  contentHash: bytea().notNull(),    // sha256(searchText); skip re-embed if unchanged

  tsv: tsvector().notNull().generatedAlwaysAs(sql`
    setweight(to_tsvector('english', coalesce(item_name, '')), 'A') ||
    setweight(to_tsvector('english', coalesce(search_text, '')), 'B')
  `),

  embedding: vector({ dimensions: EMBEDDING_DIM }),  // NULLABLE
  embeddingModel: text(),                            // null iff embedding is null
  syncedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  ...timestamps(),
}, (t) => [
  uniqueIndex("tool_embedding_item_uq").on(t.serverId, t.kind, t.itemName),
  index("tool_embedding_tsv_idx").using("gin", t.tsv),
  index("tool_embedding_vec_idx")
    .using("hnsw", t.embedding.op("vector_cosine_ops"))
    .with({ m: 16, ef_construction: 64 }),
  // serves the sync sweep: which tools still need an embedding?
  index("tool_embedding_stale_idx").on(t.serverId)
    .where(sql`embedding is null and kind = 'tool'`),
]);

// ORDERING. drizzle-kit does not emit CREATE EXTENSION, so 0000 is hand-made
// BEFORE any schema exists:
//   pnpm drizzle-kit generate --custom --name extensions   -> 0000_extensions.sql
// contents (one line):
//   CREATE EXTENSION IF NOT EXISTS vector;
// then write schema.ts and generate 0001_*.sql normally. _journal.json orders
// them, so `vector` always exists before tool_embedding is created.
// `vector` is NOT a trusted extension: it needs superuser / rds_superuser.
// IF NOT EXISTS makes 0000 a no-op when a DBA pre-installed it, which together
// with MIGRATE_ON_BOOT=false covers the no-DDL-rights operator.
// If it lives in a non-public schema, the app role's search_path must include it.

// DIM GUARD, run at boot right after migrations:
const [{ coltype }] = await db.execute<{ coltype: string }>(sql`
  select format_type(atttypid, atttypmod) as coltype
    from pg_attribute
   where attrelid = 'tool_embedding'::regclass and attname = 'embedding'`);
const dbDim = Number(coltype.match(/^vector\((\d+)\)$/)?.[1]);
if (dbDim !== EMBEDDING_DIM) {
  throw new Error(
    `tool_embedding.embedding is ${coltype} but this build expects ` +
    `vector(${EMBEDDING_DIM}). Either set EMBEDDING_DIM=${dbDim}, or add a ` +
    `migration: ALTER TABLE tool_embedding ALTER COLUMN embedding ` +
    `TYPE vector(${EMBEDDING_DIM}) USING NULL;`);
}

// MODEL CHANGE, SAME DIM (the common case): compare the configured model to
// system_setting['embedding.model']. On mismatch, one statement —
//   UPDATE tool_embedding SET embedding = NULL, embedding_model = NULL;
// then the normal sync sweep refills it. Search degrades to lexical-only for
// the minute that takes; it never returns wrong results.
//
// MODEL CHANGE, DIFFERENT DIM: needs the ALTER above as a --custom migration
// named 0NNN_embedding_dim_<N>.sql, plus a REINDEX of the hnsw index (the
// ALTER drops it; drizzle-kit regenerates the CREATE INDEX).
// ZERO-MIGRATION ESCAPE HATCH: text-embedding-3-* support Matryoshka
// truncation, so request `dimensions: 1536` from a larger model and the
// column type never changes. Prefer this.

import { index, jsonb, pgTable, text, timestamp } from "drizzle-orm/pg-core";

/** Remote registry / marketplace responses only. The bundled servers.json
 *  ships in the image and is parsed ONCE at module scope — it never touches
 *  Postgres. (mcphub re-parses its 2.4 MB file on every call, marketService.ts:12-34.) */
export const catalogCache = pgTable("catalog_cache", {
  // `${source}:${path}?${sortedQueryString}` — sorted so ?a=1&b=2 and ?b=2&a=1
  // are one entry. e.g. 'registry:/v0.1/servers?cursor=abc&limit=50'
  key: text().primaryKey(),
  body: jsonb().notNull(),
  etag: text(),
  fetchedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  index("catalog_cache_fetched_idx").on(t.fetchedAt), // the 30-day sweeper
]);

/** Serving policy (in the fetcher, not the DB):
 *   age < 15 min          -> serve, no upstream call
 *   15 min .. 30 days     -> serve immediately, revalidate in the background
 *                            with If-None-Match: etag; 304 just bumps fetchedAt
 *   > 30 days             -> treat as a miss; if upstream is down, fail loudly
 *  Sweeper: DELETE FROM catalog_cache WHERE fetched_at < now() - interval '30 days'
 */

/** Runtime-editable, cross-replica settings. Deployment facts
 *  (DATABASE_URL, MIGRATE_ON_BOOT, ENCRYPTION_KEY, PORT, EMBEDDING_DIM) are env
 *  ONLY and never appear here — env is what you cannot change without a restart. */
export const systemSetting = pgTable("system_setting", {
  key: text().primaryKey(),
  value: jsonb().notNull(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedBy: text(),   // user id, no FK — same reason as audit_event
});

// Known keys (the ONLY ones; anything else is a typo and is rejected on write):
//   embedding.provider      'openai'|'azure'|'gemini'|'none'
//   embedding.model         string
