import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import pg from "pg";

const FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));
const LOCK_KEY = 4823001; // grep this number; pairs with 4823002 (retention)

async function expectedCount(): Promise<number> {
  const j = JSON.parse(await readFile(`${FOLDER}/meta/_journal.json`, "utf8"));
  return j.entries.length;
}

async function appliedCount(c: pg.Client): Promise<number> {
  const r = await c.query(
    `select count(*)::int n from drizzle.__drizzle_migrations`,
  ).catch(() => ({ rows: [{ n: 0 }] } as never));
  return r.rows[0].n;
}

/** apply=false is MIGRATE_ON_BOOT=false: we still VERIFY, we just do no DDL. */
export async function runMigrations(url: string, apply: boolean) {
  const client = new pg.Client({ connectionString: url });
  await client.connect();
  try {
    const want = await expectedCount();
    if (!apply) {
      const have = await appliedCount(client);
      if (have !== want) {
        throw new Error(
          `Database is at ${have}/${want} migrations and MIGRATE_ON_BOOT=false. ` +
          `Run: pnpm --filter @mcprouter/core db:migrate`,
        );
      }
      return;
    }
    await client.query(`set statement_timeout = '600s'`);
    // Session-level, blocking. Replica B waits here, then finds nothing to do.
    await client.query(`select pg_advisory_lock($1)`, [LOCK_KEY]);
    await migrate(drizzle(client), { migrationsFolder: FOLDER });
  } finally {
    // Ending the session releases the advisory lock — including on crash.
    // That is why we do not call pg_advisory_unlock: there is no path where
    // a dead process leaves the lock held.
    await client.end();
  }
}

/** No seeded credentials, ever. mcphub ships admin/admin123. */
export async function ensureBootstrap(db: Db, log: Logger) {
  const [{ n }] = await db.execute<{ n: number }>(
    sql`select count(*)::int n from "user"`);
  if (n > 0) return;

  const token = randomBytes(32).toString("base64url");
  await db.insert(systemSetting).values({
    key: "bootstrap.admin",
    value: {
      tokenHash: createHash("sha256").update(token).digest("hex"),
      expiresAt: new Date(Date.now() + 24 * 3600_000).toISOString(),
    },
  }).onConflictDoUpdate({ target: systemSetting.key, set: { /* same */ } });

  log.warn({ url: `${publicUrl}/setup?token=${token}` },
    "No users exist. Open this URL to create the first admin. " +
    "It is valid for 24h and is printed only to this log.");
}

/** Claim, in the signup transaction. The DELETE ... RETURNING is the mutex:
 *  exactly one concurrent claimer gets a row back. No lock, no race. */
export async function claimBootstrap(tx: Tx, userId: string, token: string) {
  const [row] = await tx.delete(systemSetting)
    .where(and(
      eq(systemSetting.key, "bootstrap.admin"),
      sql`value->>'tokenHash' = ${sha256hex(token)}`,
      sql`(value->>'expiresAt')::timestamptz > now()`,
    ))
    .returning();
  if (!row) throw new Error("invalid or expired setup token");
  await tx.update(user).set({ role: "admin" }).where(eq(user.id, userId));
}

