import { PostgreSqlContainer } from "@testcontainers/postgresql";
import { expect, test } from "vitest";

test("migrations apply twice, tsv generates, hnsw answers", async () => {
  const pg = await new PostgreSqlContainer("pgvector/pgvector:pg16").start();
  const url = pg.getConnectionUri();

  await runMigrations(url, true);
  await runMigrations(url, true);          // idempotent
  await runMigrations(url, false);         // verify path passes when current

  const db = drizzle(url, { schema, casing: "snake_case" });
  const [u] = await db.insert(user).values({ id: "u1", email: "a@b.c", name: "a" }).returning();
  const [s] = await db.insert(servers).values({
    slug: "github", name: "GitHub", type: "stdio", ownerId: u.id,
    config: { type: "stdio", command: "npx", args: [], env: {}, requestTimeoutMs: 60000 },
  }).returning();

  await db.insert(toolEmbedding).values({
    serverId: s.id, kind: "tool", itemName: "create_issue",
    description: "Open a new issue", schemaKeys: ["repo", "title"],
    tokenCost: 42, searchText: "github GitHub: repo host\ncreate_issue\nOpen a new issue\nrepo title",
    contentHash: createHash("sha256").update("x").digest(),
    embedding: null,                       // NULL: must still rank lexically
  });

  const hit = await db.execute(sql`
    select item_name from tool_embedding
     where tsv @@ websearch_to_tsquery('english', 'open issue')`);
  expect(hit.rows).toHaveLength(1);        // generated tsvector works

  // slug CHECK blocks the '__' aliasing hole
  await expect(db.insert(servers).values({
    slug: "git_hub", name: "x", type: "stdio", ownerId: u.id,
    config: { type: "stdio", command: "x", args: [], env: {}, requestTimeoutMs: 60000 },
  })).rejects.toThrow(/servers_slug_fmt/);

  // AAD columns are enforced by length checks
  await expect(db.insert(secrets).values({
    scope: "server_env", serverId: s.id, label: "TOKEN",
    iv: Buffer.alloc(11), ciphertext: Buffer.alloc(16), tag: Buffer.alloc(16),
  })).rejects.toThrow(/secrets_iv_len/);

  await pg.stop();
}, 120_000);
